import numpy as np

C = -0.3525
K = [1, 2, 4, 5]

a_values = {}
for k in K:
    a_i = np.exp(C * k)
    a_values[k] = a_i

print("Calculated values of a_i = exp(C * k_i) for C = -0.3525 and K = {1, 2, 4, 5}:")
for k, a in a_values.items():
    print(f"k={k}: a_{k} = {a}")
